<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {mindConfig,emotionLabels,moodFace,type MindConfig} from '../lib/companionMind'
import type {ChatRuntime,ChatView,SyncView} from '../lib/companionSync'
const props=defineProps<{view:SyncView|null|undefined;native:boolean;allowWorkChat:boolean}>()
const emit=defineEmits<{received:[ChatView];workChat:[boolean]}>()
const busy=ref(false),error=ref(''),info=ref(''),tab=ref('outreach'),dirty=ref(false)
const draft=ref(mindConfig());let original=mindConfig()
watch(()=>props.view?.document.brain?.config,c=>{if(!dirty.value){original={...mindConfig(),...c};draft.value={...original}}},{immediate:true})
const brain=computed(()=>props.view?.document.brain),face=computed(()=>moodFace(props.view?.document.pet.mood??70))
const query=ref(''),filter=ref('all'),order=ref('new'),recall=ref<any>(),preview=ref<any>()
const rehearsing=ref(false),manualPending=ref(false),runtime=ref<ChatRuntime>()
const taskNames={reply:'回复聊天',manual:'准备手动气泡',interactive:'处理手动请求',automatic:'准备主动气泡',learning:'后台整理记忆'}
const progress=computed(()=>runtime.value?.cancelling?'已取消，等待当前生成收尾':runtime.value?.queuedManual?`${runtime.value.active?taskNames[runtime.value.active]:'等待调度'}中，手动搭话已排队`:runtime.value?.active?`正在${taskNames[runtime.value.active]}…`:manualPending.value?'手动搭话已提交，等待调度':'')
let runtimeTimer:ReturnType<typeof setInterval>|undefined,runtimeBusy=false,mounted=false
async function refreshRuntime(){if(!props.native||runtimeBusy)return;runtimeBusy=true;try{const value=await call('runtime');if(mounted)runtime.value=value}catch{/* The action itself reports errors. */}finally{runtimeBusy=false}}
onMounted(()=>{mounted=true;void loadLlm();void refreshRuntime();runtimeTimer=setInterval(()=>{void refreshRuntime()},500)})
onBeforeUnmount(()=>{mounted=false;clearInterval(runtimeTimer);if(manualPending.value)void call('cancelOutreach').catch(()=>{})})
const memories=computed(()=>[...(props.view?.document.memories??[])].filter(m=>!m.deleted&&(!query.value||m.text.includes(query.value))&&(filter.value==='all'||(brain.value?.memories[m.id]?.kind??(m.text.startsWith('【近况】')?'recent':m.text.startsWith('【约定】')?'agreement':'preference'))===filter.value)).sort((a,b)=>order.value==='old'?a.at-b.at:b.at-a.at))
const selected=ref<string>(),edit=ref({key:'',importance:.5,emotion:0,tags:'',kind:'recent'}),expected=ref('')
const selectedMemory=computed(()=>props.view?.document.memories.find(m=>m.id===selected.value))
watch(selected,id=>{const m=props.view?.document.memories.find(m=>m.id===id);if(m){expected.value=m.text;const meta=brain.value?.memories[m.id];edit.value={key:meta?.key??'',importance:meta?.importance??.5,emotion:meta?.emotion??0,tags:meta?.tags.join('、')??'',kind:meta?.kind??(m.text.startsWith('【近况】')?'recent':m.text.startsWith('【约定】')?'agreement':'preference')}}})
const candidates=ref<{id:string;session:string;role:string;text:string;at:number;name:string;checked:boolean}[]>([]),refined=ref<any>(),mode=ref<'import'|'enrich'>('import')
const codexModels=ref<{model:string;displayName:string;description:string;isDefault:boolean}[]>([])
const llm=ref({provider:'codex',model:'',baseUrl:'https://api.deepseek.com/v1',hasKey:false}),apiKeyInput=ref('')
const llmModels=ref<{model:string;displayName:string}[]>([])
const numeric:Record<string,{key:keyof MindConfig;label:string;min:number;max:number;step?:number}[]>={
  outreach:[{key:'intervalMinutes',label:'随机检查间隔（分钟）',min:1,max:1440},{key:'cooldownMinutes',label:'搭话冷却（分钟，0可关闭）',min:0,max:1440},{key:'dailyLimit',label:'每日自动搭话上限',min:1,max:100},{key:'probability',label:'基础命中概率（%）',min:0,max:100},{key:'missBonus',label:'随机未命中加成（百分点）',min:0,max:100},{key:'bonusCap',label:'加成上限（百分点）',min:0,max:100},{key:'quietStart',label:'安静开始（小时）',min:0,max:23},{key:'quietEnd',label:'安静结束（小时，相同则关闭）',min:0,max:23},{key:'recentMinutes',label:'刚聊过多久内降低概率（分钟）',min:0,max:1440},{key:'distantMinutes',label:'隔多久后提高概率（分钟）',min:0,max:10080}],
  memory:[{key:'memoryHalfDays',label:'事件鲜活度半衰期（天）',min:1,max:3650},{key:'maxRecall',label:'每轮最多带入条数',min:1,max:24},{key:'recallChars',label:'每轮记忆总字数',min:200,max:12000},{key:'factsMax',label:'长期事实最多占几条',min:0,max:24},{key:'dailyMemories',label:'每天新增实时记忆上限',min:1,max:1000},{key:'evidence',label:'相关性门槛（0至1）',min:0,max:1,step:.05},{key:'freshnessWeight',label:'鲜活度权重',min:0,max:1,step:.05},{key:'importanceWeight',label:'重要度权重',min:0,max:1,step:.05},{key:'emotionWeight',label:'情绪权重',min:0,max:1,step:.05}],
  mood:[{key:'confidence',label:'影响回复的可信度门槛（%）',min:0,max:100},{key:'baseline',label:'平稳心情',min:30,max:100},{key:'moodFloor',label:'心情下限（不能高于平稳值）',min:0,max:100},{key:'moodHalfHours',label:'总心情恢复半衰期（小时）',min:1,max:168},{key:'emotionHalfMinutes',label:'各情绪恢复半衰期（分钟）',min:1,max:1440}]
}
async function call(action:string,payload:unknown=null){return invoke<any>('companion_chat',{action,payload})}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';info.value='';try{await work()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function action(type:string,data:Record<string,unknown>={}){const value:ChatView=await call('brain',{type,...data});emit('received',value);return value}
async function save(){await run(async()=>{const patch=Object.fromEntries(Object.entries(draft.value).filter(([k,v])=>v!==original[k as keyof MindConfig]));const value=await action('settings',{config:patch});dirty.value=false;original={...mindConfig(),...value.status.document.brain?.config};draft.value={...original};info.value='设置已保存，并进入现有同步队列。'})}
async function rehearse(){if(rehearsing.value)return;rehearsing.value=true;error.value='';try{const value:ChatView=await call('rehearse');emit('received',value);preview.value=value.preview;info.value='演练只查看条件、动机和候选记忆；没有调用模型或发送气泡。'}catch(e){error.value=String(e)}finally{rehearsing.value=false}}
async function outreach(){await run(async()=>{manualPending.value=true;try{const value:ChatView=await call('outreach');if(mounted){emit('received',value);info.value=value.reply?'已发出一轮气泡对话。':value.status.history?.outreachStatus??'本轮未发出。'}}finally{manualPending.value=false;void refreshRuntime()}})}
async function cancelOutreach(){try{await call('cancelOutreach');info.value='已请求取消；当前生成收尾前不会启动另一轮。';await refreshRuntime()}catch(e){error.value=String(e)}}
async function lookup(){await run(async()=>{const value=await call('recall',{text:query.value});recall.value=value.preview.recall.report;emit('received',value)})}
const report=computed(()=>{if(recall.value)return recall.value;try{return JSON.parse(props.view?.history?.recallReport??'null')}catch{return null}})
async function editMemory(undo=false){const m=selectedMemory.value;if(!m)return;await run(async()=>{const value=await action(undo?'undoMemory':'editMemory',{id:m.id,expected:expected.value,...(undo?{}:{...edit.value,tags:edit.value.tags.split(/[、,，\n]/).map(t=>t.trim()).filter(Boolean)})});expected.value=value.status.document.memories.find(x=>x.id===m.id)?.text??'';info.value=undo?'已恢复上一版本。':'记忆属性已更新。'})}
const date=(at:number)=>at?new Date(at).toLocaleString():'尚无'
function dateOnly(at:number){const d=new Date(at);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function setCandidateDate(candidate:(typeof candidates.value)[number],value:string){const at=new Date(value+'T00:00:00').getTime();if(Number.isFinite(at))candidate.at=Math.min(Date.now(),at)}
async function files(event:Event){await run(async()=>{const input=event.target as HTMLInputElement,list=[...(input.files??[])];if(list.length>100)throw Error('每次最多选择100个文本文件。');const rows:typeof candidates.value=[];let bytes=0
  for(const f of list){if(!/\.(md|markdown|txt|text|log|rst|org)$/i.test(f.name)||f.webkitRelativePath.split('/').length>4)continue;bytes+=f.size;if(f.size>2*1024*1024||bytes>8*1024*1024)throw Error('单文件最多2MB，一批最多8MB。');const text=await f.text();for(const part of text.split(/\n\s*\n/)){if(part.trim().length<5)continue;for(let i=0;i<part.length;i+=3000){const value=part.slice(i,i+3000).trim();if(!value)continue;const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(f.name+'\n'+value));const id=Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');const match=value.match(/\b(20\d{2})[-/年](\d{1,2})[-/月](\d{1,2})/);const at=match?new Date(Number(match[1]),Number(match[2])-1,Number(match[3])).getTime():f.lastModified;rows.push({id,session:'archive-import',role:'user',text:value,at:Math.min(Date.now(),at||f.lastModified),name:f.name,checked:rows.length<8});if(rows.length>=100)break}if(rows.length>=100)break}if(rows.length>=100)break}
  candidates.value=rows;refined.value=undefined;mode.value='import';info.value=`找到 ${rows.length} 段候选。时间默认取文中日期或文件修改时间，可手动更正；只导入你勾选并确认的内容。`;input.value=''
})}
async function refine(enrich=false){await run(async()=>{mode.value=enrich?'enrich':'import';const sources=enrich?(props.view?.document.memories??[]).filter(m=>!m.deleted&&!brain.value?.memories[m.id]?.key).slice(0,8).map(m=>({id:m.id,session:'memory-refinement',role:'user',text:m.text.split('\n依据：')[0],at:m.at})):candidates.value.filter(c=>c.checked).map(({id,session,role,text,at})=>({id,session,role,text,at}));if(!sources.length||sources.length>8)throw Error('每批请选择1至8段资料。');refined.value=await call('previewMemories',{sources});info.value='提炼完成，请检查下方候选；尚未修改记忆。'})}
async function loadLlm(){try{const value=await call('llmGet');llm.value={provider:value.provider,model:value.model,baseUrl:value.baseUrl,hasKey:value.hasKey}}catch{/* 读取失败时保持默认 Codex。 */}}
async function saveLlm(){await run(async()=>{const value=await call('llmSet',{provider:llm.value.provider,model:llm.value.model,baseUrl:llm.value.baseUrl,apiKey:apiKeyInput.value});apiKeyInput.value='';llm.value={provider:value.provider,model:value.model,baseUrl:value.baseUrl,hasKey:value.hasKey};if(value.provider==='deepseek'){try{const list=await call('models');llmModels.value=list.models??[];if(!llm.value.model)llm.value.model=list.defaultModel??'deepseek-chat'}catch{}}info.value=value.provider==='deepseek'?`已切换到 DeepSeek（${value.model||'deepseek-chat'}）。`:'已切换到 Codex CLI。'})}
async function loadModels(){await run(async()=>{if(llm.value.provider==='deepseek'){const saved=await call('llmSet',{provider:'deepseek',model:llm.value.model,baseUrl:llm.value.baseUrl,apiKey:apiKeyInput.value});apiKeyInput.value='';llm.value={provider:saved.provider,model:saved.model,baseUrl:saved.baseUrl,hasKey:saved.hasKey};const value=await call('models');llmModels.value=value.models??[];if(!llm.value.model||!llmModels.value.some(m=>m.model===llm.value.model)){llm.value.model=value.defaultModel??'deepseek-chat'}info.value=value.source==='api'?`已从 DeepSeek 获取 ${llmModels.value.length} 个模型，请在下拉框选择。`:'未能从 DeepSeek 获取模型列表（检查 API Key 与网络），先列出内置模型。';return}const value=await call('models');codexModels.value=value.models??[];if(!draft.value.model&&value.defaultModel){draft.value.model=value.defaultModel;dirty.value=true}info.value=codexModels.value.length?`已读取 ${codexModels.value.length} 个可用 Codex 模型。`: '当前 Codex 没有返回可用模型。'})}
async function applyRefined(){await run(async()=>{if(mode.value==='import'){const value=await call('importMemories',refined.value);emit('received',value)}else{for(const a of refined.value.analyses){const m=props.view?.document.memories.find(m=>m.id===a.sourceId),meta=a.memories[0];if(m&&meta)await action('editMemory',{id:m.id,expected:m.text,key:meta.key,kind:meta.kind,importance:meta.importance,emotion:meta.emotion,tags:meta.tags})}}refined.value=undefined;info.value='已保存选定结果，并进入同步队列。'})}
</script>
<template>
  <section class="mind" aria-label="记忆心情与主动陪伴">
    <nav><button v-for="item in [{id:'outreach',text:'主动搭话'},{id:'memory',text:'记忆'},{id:'mood',text:'心情'}]" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id">{{item.text}}</button></nav>
    <div v-if="tab==='outreach'">
      <p role="status">{{view?.history?.outreachStatus||'等待下一轮检查'}}<br/><small>下一次随机机会：{{date(brain?.nextCheckAt??0)}} · 连续随机未命中 {{brain?.misses??0}} 次</small></p>
      <div class="buttons"><button :disabled="rehearsing||!native" @click="rehearse">{{rehearsing?'正在演练…':'演练一次（不发话）'}}</button><button :disabled="busy||!native" @click="outreach">{{manualPending?'已提交真发':'真发一次（跳过等待）'}}</button><button v-if="manualPending" @click="cancelOutreach">取消本轮真发</button></div>
      <p v-if="progress" role="status">{{progress}}</p>
      <small>演练不受后台整理影响。真发优先于下一批整理，允许 Codex 工作中发话，仍检查拖动、全屏、可见性和共享预约。未回应不会减频或暂停。</small>
      <label><input type="checkbox" :checked="allowWorkChat" :disabled="!native" @change="emit('workChat',($event.target as HTMLInputElement).checked)"/>Codex 工作时也允许自动搭话（仅本机）</label>
      <small>默认工作免打扰；开启后仍需满足空闲、安静时段、冷却和每日次数条件。</small>
      <p v-if="preview">演练结果：{{preview.reason}}<br/>起话动机：{{preview.motive}}<br/>候选记忆 {{preview.recall.memories.length}} 条</p>
      <details><summary>最近决策记录</summary><p v-for="(d,i) in [...(brain?.decisions??[])].reverse()" :key="i"><small>{{date(d.at)}}</small>{{d.reason}}<template v-if="d.nextAt"> · 抽到 {{d.roll.toFixed(1)}} / 命中线 {{d.chance.toFixed(1)}}%</template></p></details>
    </div>
    <div v-if="tab==='memory'">
      <input v-model="query" placeholder="查找记忆或测试一句话会想起什么" aria-label="搜索记忆"/><div class="buttons"><button :disabled="busy||!native" @click="lookup">测试召回</button><select v-model="filter" aria-label="记忆分类"><option value="all">全部</option><option value="preference">喜好</option><option value="agreement">约定</option><option value="recent">近况</option></select><select v-model="order" aria-label="记忆排序"><option value="new">新到旧</option><option value="old">旧到新</option></select></div>
      <details v-if="report"><summary>召回解释：选中 {{report.selected}} / {{report.total}} 条，{{report.chars}} 字</summary><p v-for="row in report.rows" :key="row.id"><b>{{row.selected?'✓':'—'}} {{row.reason}}</b><br/>{{row.text}}<small>相关性 {{Math.round(row.evidence*100)}}% · 鲜活度 {{Math.round(row.freshness*100)}}% · 重要度 {{Math.round(row.importance*100)}}%</small></p><small v-if="report.truncated">仅展示评分前80条。</small></details>
      <div class="memory-list"><button v-for="m in memories.slice(0,100)" :key="m.id" @click="selected=m.id"><small>{{date(m.at)}}</small>{{m.text.split('\n')[0]}}</button></div>
      <details v-if="selectedMemory" open><summary>编辑选中记忆</summary><p class="source">{{selectedMemory.text}}</p><label>分类<select v-model="edit.kind"><option value="preference">喜好</option><option value="agreement">约定</option><option value="recent">近况</option></select></label><label>事实键<input v-model="edit.key" maxlength="60"/></label><label>重要度<input v-model.number="edit.importance" type="number" min="0" max="1" step="0.1"/></label><label>情绪权重<input v-model.number="edit.emotion" type="number" min="0" max="1" step="0.1"/></label><label>检索词（顿号分隔）<input v-model="edit.tags"/></label><div class="buttons"><button :disabled="busy||!native" @click="editMemory()">保存属性</button><button :disabled="busy||!native||!brain?.memories[selectedMemory.id]?.versions.length" @click="editMemory(true)">撤销到上一版本</button></div><p v-for="(v,i) in brain?.memories[selectedMemory.id]?.versions??[]" :key="i"><small>旧版本 {{date(v.at)}}</small>{{v.text}}</p></details>
      <details><summary>旧文本档案导入 / 补充旧记忆检索词</summary><small>支持 Markdown、TXT、LOG、RST、ORG。文件夹向下最多两层；先预览，再确认保存。提炼使用当前模型，可能产生调用费用。</small><label>选择文本文件<input type="file" multiple accept=".md,.markdown,.txt,.text,.log,.rst,.org" :disabled="busy||!native" @change="files"/></label><label>选择文件夹<input type="file" multiple webkitdirectory :disabled="busy||!native" @change="files"/></label><div class="candidates"><label v-for="c in candidates" :key="c.id"><input v-model="c.checked" type="checkbox"/>{{c.name}}：{{c.text.slice(0,180)}}<input type="date" :value="dateOnly(c.at)" @change="setCandidateDate(c,($event.target as HTMLInputElement).value)"/></label></div><div class="buttons"><button :disabled="busy||!native" @click="refine()">提炼勾选资料（最多8段）</button><button :disabled="busy||!native" @click="refine(true)">试补旧记忆（最多8条）</button></div><div v-if="refined"><p v-for="a in refined.analyses" :key="a.sourceId">{{a.memories.map((m:any)=>m.text+'；键：'+m.key+'；词：'+m.tags.join('、')).join('\n')||'未提取可信事实，跳过'}}</p><button :disabled="busy" @click="applyRefined">确认保存以上结果</button><button @click="refined=undefined">取消</button></div></details>
    </div>
    <div v-if="tab==='mood'">
      <p>{{face.icon}} {{face.label}} {{Math.round(view?.document.pet.mood??70)}} · {{view?.document.pet.moodReason||'平稳陪伴'}}</p>
      <div class="emotions"><label v-for="(label,key) in emotionLabels" :key="key">{{label}}<meter min="0" max="100" :value="brain?.emotions[key]??0"/>{{(brain?.emotions[key]??0).toFixed(1)}}</label></div>
      <details><summary>心情时间线</summary><p v-for="event in [...(brain?.timeline??[])].reverse()" :key="event.id"><small>{{date(event.at)}} · {{event.source==='speak-up'?'主动找你':'你的消息'}} · 把握 {{event.confidence}}%</small>{{event.delta>0?'+':''}}{{event.delta}}：{{event.reason}}<small>{{Object.entries(event.dims).filter(([,v])=>v>=1).map(([k,v])=>emotionLabels[k]+' '+v.toFixed(1)).join(' · ')}}</small></p><small v-if="!brain?.timeline.length">旧版总分记录仍保留在备份；新增互动将在这里展示细分情绪。</small></details>
      <details><summary>它会听到什么</summary><p>当前方式：{{draft.injectMode==='off'?'不影响回复':draft.injectMode==='state'?'当前状态':'新事件只带入一次'}}</p><p v-if="brain?.event">最新判断：{{brain.event.reason}} · 把握 {{brain.event.confidence}}%<br/>{{brain.event.confidence<draft.confidence?'可信度不足，只留后台':(brain.event.id===brain.consumed||brain.consumedIds?.includes(brain.event.id))?'已经带入过':'等待下一轮带入'}}</p><p v-if="brain?.injection">实际带入（{{date(brain.injectedAt)}}）：{{brain.injection}}</p></details>
      <button :disabled="busy||!native" @click="run(async()=>{await action('resetMood');info='心情已重置，时间线已清空。'})">重置到平稳心情</button>
    </div>
<div v-if="tab==='mood'" class="llm"><p><strong>模型来源</strong><br/><small>默认 Codex CLI；切到 DeepSeek 后气泡聊天、记忆整理、主动搭话都走 DeepSeek API。</small></p><label>Provider<select v-model="llm.provider"><option value="codex">Codex CLI</option><option value="deepseek">DeepSeek API</option></select></label><template v-if="llm.provider==='deepseek'"><label>DeepSeek API Key<input v-model="apiKeyInput" type="password" maxlength="400" :placeholder="llm.hasKey?'已保存，留空则沿用':'sk-...'"/></label><label>Base URL<input v-model="llm.baseUrl" maxlength="300"/></label><label>DeepSeek 模型<select v-if="llmModels.length" v-model="llm.model"><option v-for="m in llmModels" :key="m.model" :value="m.model">{{m.displayName||m.model}}</option></select><input v-else v-model="llm.model" maxlength="100" placeholder="deepseek-chat"/></label></template><div class="buttons"><button :disabled="busy||!native" @click="loadModels">获取可用模型</button><button :disabled="busy||!native" @click="saveLlm">保存模型来源</button></div></div>
    <details @input="dirty=true"><summary>调整{{tab==='outreach'?'搭话节奏':tab==='memory'?'记忆参数':'心情设置'}}</summary>
      <label v-for="n in numeric[tab]" :key="n.key">{{n.label}}<input v-model.number="draft[n.key]" type="number" :min="n.min" :max="n.max" :step="n.step??1"/></label>
      <template v-if="tab==='outreach'"><label><input v-model="draft.dryRun" type="checkbox"/>试运行：自动命中只记记录</label><label>起话动机<textarea v-model="draft.motive" maxlength="400"/></label><small>刚聊过时概率×0.15，隔很久后×1.5；未命中加成只作用于随机抽取。</small></template>
      <template v-if="tab==='memory'"><label>你的称呼<input v-model="draft.userName" maxlength="40"/></label><label>桌宠名字<input v-model="draft.petName" maxlength="40"/></label><label>记忆中你的代称<input v-model="draft.pronoun" maxlength="40"/></label><small>长期喜好和约定保持稳定；日常事件连续淡化，重复提及会强化。每日新增配额不阻止历史档案补全。</small></template>
      <template v-if="tab==='mood'"><label><input v-model="draft.moodEnabled" type="checkbox"/>实时判断心情</label><label>心情如何影响回复<select v-model="draft.injectMode"><option value="off">不影响回复</option><option value="state">提供当前状态</option><option value="event">新感受只带入一次</option></select></label><label><input v-model="draft.romance" type="checkbox"/>允许甜蜜和吃醋倾向</label><label><input v-model="draft.animations" type="checkbox"/>心情变化联动动作</label><label><input v-model="draft.badge" type="checkbox"/>显示桌宠心情标记</label><label>Codex / 记忆整理模型<small v-if="llm.provider==='deepseek'">（仅 Codex 模式生效；DeepSeek 用上面的 DeepSeek 模型）</small><select v-if="codexModels.length" v-model="draft.model" :disabled="llm.provider==='deepseek'"><option value="">自动选择</option><option v-for="model in codexModels" :key="model.model" :value="model.model">{{model.displayName}}（{{model.model}}）{{model.isDefault?' · 默认':''}}</option></select><input v-else v-model="draft.model" maxlength="100" :disabled="llm.provider==='deepseek'" placeholder="点击下方按钮读取可用模型；留空自动选择"/></label><div class="buttons"><button :disabled="busy||!native" @click="loadModels">{{llm.provider==='deepseek'?'读取 DeepSeek 可用模型':'读取 Codex 可用模型'}}</button></div><small v-if="codexModels.length">列表来自当前 Codex 账户；选择后点击“保存设置”生效。</small></template>
    </details>
    <div v-if="dirty" class="save"><span>设置有改动</span><button :disabled="busy||!native" @click="save">保存设置</button><button @click="dirty=false;draft={...mindConfig(),...brain?.config};original={...draft}">放弃</button></div>
    <p v-if="busy" role="status">正在处理…</p><p v-if="info" role="status">{{info}}</p><p v-if="error" class="error" role="alert">{{error}}</p>
  </section>
</template>
